53	// handlePlanConfiguration computes the diff between a desired configuration
54	// and a prior state. It only computes the plan; nothing is applied or
55	// persisted.
56	func handlePlan(w http.ResponseWriter, r *http.Request) {
57		w.Header().Set("Content-Type", "application/json; charset=utf-8")
58		if r.Method != http.MethodPost {
59			rejectMethodNotAllowed(w)
