133	// checkPlanEnvelope validates the request envelope: a JSON object holding
134	// exactly the configuration and priorState fields. On failure it writes the
135	// 422 response and returns ok=false.
136	func checkPlanEnvelope(w http.ResponseWriter, doc any) (configuration, priorState any, ok bool) {
137		var errs []validationError
138		add := func(code, message, path string) {
139			errs = append(errs, validationError{Code: code, Message: message, Path: path})
140		}
141	
142		root, isObject := doc.(map[string]any)
143		if !isObject {
144			add(codeInvalidPlanRequest, "request body must be a JSON object", "")
145		} else {
146			for key := range root {
147				if key != "configuration" && key != "priorState" {
148					add(codeInvalidPlanRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
149				}
150			}
151			var hasConfig, hasState bool
152			configuration, hasConfig = root["configuration"]
153			priorState, hasState = root["priorState"]
154			if !hasConfig {
155				add(codeInvalidPlanRequest, `missing required field "configuration"`, "")
156			}
157			if !hasState {
158				add(codeInvalidPlanRequest, `missing required field "priorState"`, "")
159			}
