normalizeObserved:

```go
// normalizeObserved validates one observed snapshot and re-expresses it in
// the canonical form used for comparison and output: dependencies sorted
// ascending and properties round-tripped through JSON so they hold only
// plain decoded JSON values. An invalid snapshot is an observer contract
// violation and reported as observer_invalid_result.
func normalizeObserved(snapshot *Snapshot) (Snapshot, error) {
	if snapshot.Type == "" {
		return Snapshot{}, fmt.Errorf("observed snapshot for a present resource must have a non-empty type")
	}
	if snapshot.Properties == nil {
		return Snapshot{}, fmt.Errorf("observed snapshot for a present resource must have non-nil properties")
	}
	encoded, err := json.Marshal(snapshot.Properties)
	if err != nil {
		return Snapshot{}, fmt.Errorf("observed properties cannot be encoded as JSON: %v", err)
	}
	dec := json.NewDecoder(bytes.NewReader(encoded))
	dec.UseNumber()
	var decoded any
	if err := dec.Decode(&decoded); err != nil {
		return Snapshot{}, fmt.Errorf("observed properties cannot be encoded as JSON: %v", err)
	}
	properties, ok := decoded.(map[string]any)
	if !ok {
		return Snapshot{}, fmt.Errorf("observed properties must encode as a JSON object")
	}

	seen := make(map[string]bool, len(snapshot.DependsOn))
	dependsOn := make([]string, len(snapshot.DependsOn))
	for i, dep := range snapshot.DependsOn {
		if dep == "" {
			return Snapshot{}, fmt.Errorf("observed dependsOn contains an empty address")
		}
		if seen[dep] {
			return Snapshot{}, fmt.Errorf("observed dependsOn contains duplicate %q", dep)
		}
		seen[dep] = true
		dependsOn[i] = dep
	}
	sort.Strings(dependsOn)
	return Snapshot{Type: snapshot.Type, Properties: properties, DependsOn: dependsOn}, nil
}
```

